window.addEventListener('load', function() {

let toggleButton=document.querySelector(".header__action--dark-mode"),icon=toggleButton.querySelector("i"),body=document.body;function enableDarkMode(){body.classList.add("light-mode"),icon.classList.replace("fa-moon","fa-sun"),localStorage.setItem("light-mode","enabled")}function disableDarkMode(){body.classList.remove("light-mode"),icon.classList.replace("fa-sun","fa-moon"),localStorage.setItem("light-mode","disabled")}"enabled"===localStorage.getItem("light-mode")&&enableDarkMode(),toggleButton.addEventListener("click",()=>{(body.classList.contains("light-mode")?disableDarkMode:enableDarkMode)()});
});